const GROUP_PLAIN = {
  '6': ['One of the nine regions of the Great Vesicle: what it is like, who is there and what goes wrong.', 'Choosing or describing this place.'],
  '7': ['One of the six powers: what it says, wants, fears, pays in and how to voice it.', 'This faction is in the scene.'],
};
const plainFor = (s) => {
  const k = P[s.sec];
  if (k) return k;
  if (/^6\.\d/.test(s.sec)) return GROUP_PLAIN['6'];
  if (/^7\.\d/.test(s.sec)) return GROUP_PLAIN['7'];
  return [`${s.title}.`, 'It comes up at the table.'];
};

export const CODEX = CODEX_SECTIONS.map((s) => {
  const [plain, when] = plainFor(s);
  return {
    id: s.id, ch: `Codex ${s.sec}`, name: `${s.sec} ${s.title}`, plain, when,
    who: 'Director reads it; the Engine holds the numbers in the AI game.',
    rule: s.lines, table: '', keys: `${s.title} ${CODEX_CHAPTERS[s.chapter] || ''}`,
    chapter: s.chapter, sec: s.sec,
  };
});
export { CODEX_CHAPTERS };
